const setReservationStatus = `-- name: SetReservationStatus :execrows
UPDATE pharmacy_reservations SET status = $1,
  cancel_reason = CASE WHEN $2::text <> '' THEN $2::text ELSE cancel_reason END,
  completed_at = CASE WHEN $1 = 'completed' THEN now() ELSE completed_at END,
  updated_at = now()
WHERE id = $3 AND status = ANY($4::text[])
`

type SetReservationStatusParams struct {
	NewStatus    string
	Reason       string
	ID           uuid.UUID
	FromStatuses []string
}

func (q *Queries) SetReservationStatus(ctx context.Context, arg SetReservationStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setReservationStatus,
		arg.NewStatus,
		arg.Reason,
		arg.ID,
		arg.FromStatuses,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

