const succeededOrderPayment = `-- name: SucceededOrderPayment :one
SELECT id, purpose, alert_id, reservation_id, buyer_id, provider, reference, provider_ref, amount_xof, currency, operator, payer_phone, status, failure_reason, succeeded_at, refund_reference, created_at, updated_at FROM pharmacy_payments WHERE reservation_id = $1 AND purpose = 'order' AND status = 'succeeded'
ORDER BY created_at LIMIT 1
`

func (q *Queries) SucceededOrderPayment(ctx context.Context, reservationID *uuid.UUID) (PharmacyPayment, error) {
	row := q.db.QueryRow(ctx, succeededOrderPayment, reservationID)
	var i PharmacyPayment
	err := row.Scan(
		&i.ID,
		&i.Purpose,
		&i.AlertID,
		&i.ReservationID,
		&i.BuyerID,
		&i.Provider,
		&i.Reference,
		&i.ProviderRef,
		&i.AmountXof,
		&i.Currency,
		&i.Operator,
		&i.PayerPhone,
		&i.Status,
		&i.FailureReason,
		&i.SucceededAt,
		&i.RefundReference,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

